package server

import (
	"context"
	"path/filepath"
	"testing"

	archive "proxycontrol/internal/panel/system/backup"
	"proxycontrol/internal/platform/config"
	"proxycontrol/internal/platform/db"
)

// TestPreRefactorBackupRestores stages a backup archive produced by the
// pre-refactor baseline (commit de6a681), opens the staged database with the
// current code so migrations run forward, and checks that business data still
// restores while the receipt-archive tables removed in migration 0099 are gone.
//
// The fixture is generated by internal/platform/server/testdata/generate_prerefactor.
func TestPreRefactorBackupRestores(t *testing.T) {
	ctx := context.Background()
	archivePath := filepath.Join("testdata", "prerefactor_backup.pcb")
	const password = "fixture-backup-password"
	targetDirectory := t.TempDir()
	panel := config.DefaultPanel()
	panel.Database = filepath.Join(targetDirectory, "panel.db")
	panel.NodeIdentityDirectory = filepath.Join(targetDirectory, "identity")
	prepared, err := archive.PrepareRestore(ctx, t.TempDir(), archivePath, password, archive.RestoreTarget{Panel: panel, ConfigurationPath: filepath.Join(targetDirectory, "panel.yaml")})
	if err != nil {
		t.Fatalf("prepare restore: %v", err)
	}
	staged := filepath.Join(prepared.Directory, "database", "panel.db")
	restored, err := db.Open(ctx, staged)
	if err != nil {
		t.Fatalf("open staged database: %v", err)
	}
	defer restored.Close()
	for _, check := range []struct{ table, column, value string }{
		{"users", "username", "fixture_user"},
		{"node_groups", "name", "Fixture Group"},
		{"policies", "name", "Fixture block"},
	} {
		var count int
		if err := restored.QueryRowContext(ctx, "SELECT count(*) FROM "+check.table+" WHERE "+check.column+"=?", check.value).Scan(&count); err != nil || count != 1 {
			t.Fatalf("restored %s %q missing: %d %v", check.table, check.value, count, err)
		}
	}
	var dropped int
	if err := restored.QueryRowContext(ctx, "SELECT count(*) FROM sqlite_master WHERE type='table' AND name IN ('access_receipt_archives','traffic_receipt_archives','receipt_archive_job','receipt_archive_cursors','node_identity_recovery_decisions','recovery_evidence_results','recovery_accounting_checks','recovery_traffic_executions','recovery_revision_applications','recovery_message_completions','recovery_update_completions','recovery_agent_result_completions','recovery_core_result_completions','recovery_final_settlements','recovery_connection_completions','recovery_connection_adoptions','recovery_budget_adoptions','recovery_budget_unknown_dispositions','controller_handoff_completions','controller_isolation_evidence','controller_isolation_approvals','node_loss_dispositions','node_identity_replacements','node_loss_state_reviews','node_identity_isolations')").Scan(&dropped); err != nil || dropped != 0 {
		t.Fatalf("receipt-archive or recovery-case tables survived migration: %d %v", dropped, err)
	}
	var caDropped int
	if err := restored.QueryRowContext(ctx, "SELECT count(*) FROM sqlite_master WHERE type='table' AND name IN ('node_ca_successor_retirement_assessments','node_ca_successor_rounds','node_ca_trust_receipts','node_ca_transition','node_ca_retirement_receipts','node_ca_global_retirement','node_ca_recovered_root','node_ca_operation_requests','recovery_identity_completions','recovery_case_decisions','recovery_case_issues','recovery_cases','owner_expired_certificate_renewals','recovery_owner_credentials')").Scan(&caDropped); err != nil || caDropped != 0 {
		t.Fatalf("CA-round or recovery-case tables survived migration 0101: %d %v", caDropped, err)
	}
	var budgetDropped int
	if err := restored.QueryRowContext(ctx, "SELECT count(*) FROM sqlite_master WHERE type='table' AND name IN ('user_node_budgets','user_node_budget_versions','quota_conversions','quota_conversion_targets','unissued_budget_returns','budget_return_tasks','budget_return_commands','issued_budget_returns','budget_transfer_auto_events','budget_transfer_target_returns','budget_transfer_redirects','budget_transfer_reclaims','budget_transfer_tasks','recovered_budget_retirements','deployment_final_usage','runtime_final_usage','runtime_sources','node_pause_attempts','node_pause_tasks','user_node_connection_retirements','user_node_connections','user_connection_limits')").Scan(&budgetDropped); err != nil || budgetDropped != 0 {
		t.Fatalf("budget/connection-ledger tables survived migration 0102: %d %v", budgetDropped, err)
	}
	var liveDropped int
	if err := restored.QueryRowContext(ctx, "SELECT count(*) FROM sqlite_master WHERE type='table' AND name IN ('node_live_connections','node_live_connection_accounts')").Scan(&liveDropped); err != nil || liveDropped != 0 {
		t.Fatalf("live connection tables survived migration 0103: %d %v", liveDropped, err)
	}
	var forkObservationDropped int
	if err := restored.QueryRowContext(ctx, "SELECT count(*) FROM sqlite_master WHERE type='table' AND name IN ('connection_observations','connection_observation_cursors','connection_observation_gaps','egress_associations','egress_replay_guards','egress_replay_sources')").Scan(&forkObservationDropped); err != nil || forkObservationDropped != 0 {
		t.Fatalf("fork observation tables survived migration 0105: %d %v", forkObservationDropped, err)
	}
}
